import { Injectable } from "@nestjs/common";
import { Api, AuthorDto } from "../textbase.api";

/**
 * wrapper over the api generated by swagger-typescript-api
 */
@Injectable()
export class TextbaseClient {
    protected tb: Api<string>;

    constructor() {
        this.tb = new Api({
            // baseUrl: 'http://localhost:8080',
            baseUrl: 'http://textbase.scriptorium.ro',
            baseApiParams: {
              headers: {
                Accept: 'application/json',
              }
            }
          })
    }

    async getAuthors() : Promise<AuthorDto[]> {
        const resp = await this.tb.api.getAuthors();
        const authors = (resp).data;
        return authors;
    }

    async getOpera(strId: string) {
        const opera = (await this.tb.api.getOpera(strId)).data
        return opera;
    }

    async getParagraphs(opId: number) {
        const paras = (await this.tb.api.getIdParas(opId, {
            page: 0, 
            size: 100, 
            withContent: 'true'
          })).data
          return paras;
    }
}